    <script>
        /* ========== 获取消息内容 ========== */
        function getMessageData() {
            var chatMessages = getChatMessages(getCurrentMessageId());
            if (!chatMessages || chatMessages.length === 0) {
                console.error("无法获取消息内容");
                return null;
            }
            return chatMessages[0].message;
        }

        /* ========== 提取live_status标签内容 ========== */
        function extractLiveStatus(messageText) {
            var match = messageText.match(/<live_status>([\s\S]*?)<\/live_status>/);
            if (match && match[1]) {
                return match[1].trim();
            }
            return null;
        }

        /* ========== 解析front区块 ========== */
        function parseFront(content) {
            var frontMatch = content.match(/<front>([\s\S]*?)<\/front>/);
            if (!frontMatch || !frontMatch[1]) return null;

            var frontContent = frontMatch[1];
            var result = {
                sceneDesc: "",
                danmakuList: []
            };

            /* 解析画面描述 */
            var descMatch = frontContent.match(/\[画面描述\|([^\]]+)\]/);
            if (descMatch && descMatch[1]) {
                result.sceneDesc = descMatch[1].trim();
            }

            /* 解析弹幕 */
            var danmakuRegex = /\[弹幕\|([^\|]+)\|([^\]]+)\]/g;
            var dm;
            while ((dm = danmakuRegex.exec(frontContent)) !== null) {
                result.danmakuList.push({
                    type: dm[1].trim(),
                    text: dm[2].trim()
                });
            }

            return result;
        }

        /* ========== 解析back区块 ========== */
        function parseBack(content) {
            var backMatch = content.match(/<back>([\s\S]*?)<\/back>/);
            if (!backMatch || !backMatch[1]) return null;

            var backContent = backMatch[1];
            var result = {};

            var fields = ["衣着", "姿势", "嘴巴", "胸部", "屁股", "小穴", "屁穴"];
            fields.forEach(function(field) {
                var regex = new RegExp("\\[" + field + "\\|([^\\]]+)\\]");
                var match = backContent.match(regex);
                result[field] = match && match[1] ? match[1].trim() : "未记录";
            });

            return result;
        }

        /* ========== 渲染直播正面 ========== */
        function renderFront(frontData) {
            /* 画面描述 */
            var sceneEl = document.getElementById("sceneDesc");
            if (sceneEl) {
                sceneEl.textContent = frontData.sceneDesc || "直播画面加载中...";
            }

            /* 弹幕 */
            var trackEl = document.getElementById("danmakuTrack");
            if (!trackEl || !frontData.danmakuList.length) return;

            var danmakuHTML = "";
            var hasGold = false;
            frontData.danmakuList.forEach(function(dm) {
                var cssClass = "danmaku-item ";
                if (dm.type === "金色" || dm.type === "金" || dm.type.indexOf("金") !== -1) {
                    cssClass += "danmaku-gold";
                    hasGold = true;
                } else {
                    cssClass += "danmaku-white";
                }
                danmakuHTML += '<div class="' + cssClass + '">' + dm.text + '</div>';
            });
            trackEl.innerHTML = danmakuHTML;

            /* 礼物提示条 */
            var giftBar = document.getElementById("giftBar");
            if (giftBar && hasGold) {
                giftBar.textContent = "💰 金主正在观看 · 礼物进行中";
                giftBar.style.display = "block";
            } else if (giftBar) {
                giftBar.style.display = "none";
            }

            /* 观众数 */
            var viewerEl = document.getElementById("viewerNum");
            if (viewerEl) {
                var count = 15 + Math.floor(Math.random() * 20);
                viewerEl.textContent = count;
            }
        }

        /* ========== 渲染状态栏反面 ========== */
        function renderBack(backData) {
            var listEl = document.getElementById("statusList");
            if (!listEl || !backData) return;

            var fields = ["衣着", "姿势", "嘴巴", "胸部", "屁股", "小穴", "屁穴"];
            var html = "";
            fields.forEach(function(field) {
                var value = backData[field] || "未记录";
                html += '<div class="status-item">';
                html += '<div class="status-label">' + field + '</div>';
                html += '<div class="status-value">' + value + '</div>';
                html += '</div>';
            });
            listEl.innerHTML = html;
        }

        /* ========== 翻转控制 ========== */
        function setupFlip() {
            var btn = document.getElementById("flipBtn");
            var inner = document.getElementById("cardInner");
            if (!btn || !inner) return;

            var isFlipped = false;
            btn.addEventListener("click", function() {
                isFlipped = !isFlipped;
                if (isFlipped) {
                    inner.classList.add("flipped");
                    btn.textContent = "⟲";
                } else {
                    inner.classList.remove("flipped");
                    btn.textContent = "⟳";
                }
            });
        }

        /* ========== 主函数 ========== */
        function init() {
            try {
                var messageText = getMessageData();
                if (!messageText) {
                    document.getElementById("sceneDesc").textContent = "❌ 无法获取消息内容";
                    return;
                }

                var liveStatusContent = extractLiveStatus(messageText);
                if (!liveStatusContent) {
                    document.getElementById("sceneDesc").textContent = "直播已结束";
                    document.getElementById("danmakuTrack").innerHTML = "";
                    document.getElementById("statusList").innerHTML =
                        '<div class="loading">暂无状态数据</div>';
                    return;
                }

                /* 解析数据 */
                var frontData = parseFront(liveStatusContent);
                var backData = parseBack(liveStatusContent);

                /* 渲染 */
                if (frontData) {
                    renderFront(frontData);
                } else {
                    document.getElementById("sceneDesc").textContent = "直播画面解析失败";
                }

                if (backData) {
                    renderBack(backData);
                } else {
                    document.getElementById("statusList").innerHTML =
                        '<div class="loading">状态数据解析失败</div>';
                }

                /* 初始化翻转 */
                setupFlip();

            } catch (error) {
                console.error("错误:", error);
                document.getElementById("sceneDesc").textContent =
                    "❌ 加载失败：" + error.message;
                document.getElementById("statusList").innerHTML =
                    '<div class="loading">❌ 加载失败</div>';
            }
        }

        $(function() { init(); });
    </script>
</body>
</html>
